import os, csv, json
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190127", "20190128"]
targets = ["冀宁线", "川气东送"]

rows = []
for d in dates:
    with open(DIR / f"{d}_pipeline.csv", encoding="utf-8") as f:
        for r in csv.DictReader(f):
            if r["管道划分"] in targets:
                rows.append({
                    "date": d,
                    "line": r["管道划分"],
                    "seg": f'{r["起点站名"]}->{r["终点站名"]}',
                    "flow": float(r["管道流量"]),
                })

out = {}
for line in targets:
    sub = [r for r in rows if r["line"] == line]
    zero = [r for r in sub if abs(r["flow"]) == 0]
    out[line] = {
        "total": len(sub),
        "zero_days": len(zero),
        "zero_ratio": len(zero) / len(sub) if sub else None,
        "zero_rows": zero,
    }

# top 3 segments by zero count (across both lines)
seg_zero = {}
for r in rows:
    if abs(r["flow"]) == 0:
        seg_zero[r["seg"]] = seg_zero.get(r["seg"], 0) + 1
top3 = sorted(seg_zero.items(), key=lambda x: -x[1])[:3]

print(json.dumps({"by_line": out, "top3_zero_segments": top3}, ensure_ascii=False, indent=2))

