import os
import csv
from pathlib import Path

# Read pipeline data
pipeline_dir = Path(os.environ["PIPELINE_FLOW_DIR"])
pipeline_file = pipeline_dir / "20191206_pipeline.csv"

# Read node data
node_dir = Path(os.environ["NODE_FLOW_DIR"])
node_file = node_dir / "20191206_node.csv"

# Parse pipeline data - focus on 冀宁线
jining_segments = []
with open(pipeline_file, 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['管道划分'] == '冀宁线':
            jining_segments.append({
                'from': row['起点站名'],
                'to': row['终点站名'],
                'flow': float(row['管道流量'])
            })

print("=== 冀宁线管段 ===")
for seg in jining_segments:
    print(f"  {seg['from']} -> {seg['to']} (流量: {seg['flow']})")

# Parse node data - find gas sources (气源)
gas_sources = []
with open(node_file, 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['类型'] == '气源':
            gas_sources.append({
                'pipeline': row['管道划分'],
                'station': row['站名'],
                'input_flow': float(row['输入流量']) if row['输入流量'] else 0
            })

print("\n=== 所有气源 ===")
for src in gas_sources:
    print(f"  {src['pipeline']} - {src['station']} (输入流量: {src['input_flow']})")

# Build adjacency for 冀宁线 only
adjacency = {}
for seg in jining_segments:
    adjacency.setdefault(seg['from'], []).append(seg['to'])
    adjacency.setdefault(seg['to'], []).append(seg['from'])

print("\n=== 冀宁线邻接表 ===")
for node, neighbors in adjacency.items():
    print(f"  {node}: {neighbors}")

# BFS from each gas source to 石家庄站 on 冀宁线
target = '石家庄站'
print(f"\n=== 从各气源到{target}的最短路径 (冀宁线) ===")

# Find gas sources that are on 冀宁线
jining_sources = [src for src in gas_sources if src['pipeline'] == '冀宁线']
print(f"冀宁线上的气源: {[s['station'] for s in jining_sources]}")

# BFS from each source
from collections import deque

def bfs_shortest_path(adjacency, start, end):
    if start == end:
        return [start]
    queue = deque([(start, [start])])
    visited = {start}
    while queue:
        node, path = queue.popleft()
        for neighbor in adjacency.get(node, []):
            if neighbor == end:
                return path + [neighbor]
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

for src in jining_sources:
    path = bfs_shortest_path(adjacency, src['station'], target)
    if path:
        print(f"  {src['station']} -> {target}: {' -> '.join(path)} ({len(path)-1} 跳)")
    else:
        print(f"  {src['station']} -> {target}: 不可达")

# Also check all gas sources reachable via 冀宁线
print(f"\n=== 所有气源到{target}的最短路径 (冀宁线) ===")
for src in gas_sources:
    path = bfs_shortest_path(adjacency, src['station'], target)
    if path:
        print(f"  {src['station']} -> {target}: {' -> '.join(path)} ({len(path)-1} 跳)")
    else:
        print(f"  {src['station']} -> {target}: 不可达")

import os
import csv
from pathlib import Path
from collections import deque

NODE_FILE = Path(os.environ["NODE_FLOW_DIR"]) / "20191206_node.csv"
PIPELINE_FILE = Path(os.environ["PIPELINE_FLOW_DIR"]) / "20191206_pipeline.csv"

# Load nodes: find gas sources (气源) on 西气东输二线
sources = set()
with open(NODE_FILE, encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row["管道划分"] == "西气东输二线" and row["类型"] == "气源":
            sources.add(row["站名"])

print("气源 (西气东输二线):", sources)

# Load pipeline segments for 西气东输二线, build undirected adjacency
adj = {}
with open(PIPELINE_FILE, encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row["管道划分"] == "西气东输二线":
            a, b = row["起点站名"], row["终点站名"]
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)

print("\nAdjacency (西气东输二线):")
for k, v in adj.items():
    print(f"  {k} -> {v}")

# BFS from 华阴站 to find shortest path to any source
target = "华阴站"
if target not in adj:
    print(f"\n{target} not found in adjacency!")
else:
    visited = {target}
    queue = deque([(target, [])])
    found = None
    while queue:
        node, path = queue.popleft()
        if node in sources:
            found = (node, path)
            break
        for nb in adj.get(node, []):
            if nb not in visited:
                visited.add(nb)
                queue.append((nb, path + [nb]))

    if found:
        src, path = found
        print(f"\n最近气源: {src}")
        print(f"最短路径: {' -> '.join([target] + path)}")
        print(f"路径长度: {len(path)} 段")
    else:
        print(f"\n从 {target} 无法到达任何气源!")

# Also check all sources reachability
print("\n--- 所有气源可达性 ---")
for s in sorted(sources):
    visited = {target}
    queue = deque([(target, [])])
    found = None
    while queue:
        node, path = queue.popleft()
        if node == s:
            found = path
            break
        for nb in adj.get(node, []):
            if nb not in visited:
                visited.add(nb)
                queue.append((nb, path + [nb]))
    if found:
        print(f"  {s}: 可达, 路径长度 {len(found)} 段, 路径: {' -> '.join([target] + found)}")
    else:
        print(f"  {s}: 不可达")

