import os
import csv
from pathlib import Path

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
csv_path = DIR / "20190211_pipeline.csv"

segments = []
with open(csv_path, "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row["管道划分"] == "中俄东线" and row["类型"] == "管段":
            flow = float(row["管道流量"])
            segments.append({
                "起点站名": row["起点站名"],
                "终点站名": row["终点站名"],
                "管道流量": flow,
            })

zero_flow = [s for s in segments if s["管道流量"] == 0]
neg_flow = [s for s in segments if s["管道流量"] < 0]

print("=== 零流量管段 ===")
if zero_flow:
    for s in zero_flow:
        print(f"{s['起点站名']} -> {s['终点站名']}: {s['管道流量']}")
else:
    print("无")

print("\n=== 负流量管段 ===")
if neg_flow:
    for s in neg_flow:
        print(f"{s['起点站名']} -> {s['终点站名']}: {s['管道流量']}")
else:
    print("无")

print("\n=== 负荷最高的前 2 个区段 ===")
top2 = sorted(segments, key=lambda x: x["管道流量"], reverse=True)[:2]
for s in top2:
    print(f"{s['起点站名']} -> {s['终点站名']}: {s['管道流量']}")

